            while True:
                row=pos+1
                ok=True
                while row<h:
                    if (row,j) in fixed or any((row==r) for r in []): pass
                    if g[row][j]!=bg and (row,j) not in fixed: ok=False; break
                    row+=1
                if ok: break
            # this greedy approach is slow; just do pure gravity per column ignoring fixed for now
        rem=list(range(h))
