def grav(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    moved=True
    while moved:
        moved=False
        for i in range(h-1,-1,-1):
            for j in range(w):
                v=g[i][j]
                if v!=0 and i+1<h and g[i+1][j]==0:
                    g[i][j],g[i+1][j]=0,v; moved=True
    return g
